import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a thrown string with its cause while preserving the rejection [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const errors: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeUserInput: async () => {
          throw 'string boom';
        },
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );

  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false, reason: undefined}),
    (reason: unknown) => ({rejected: true, reason})
  );

  expect({
    outcome,
    count: errors.length,
    isError: errors[0] instanceof Error,
    message: errors[0]?.message,
    cause: errors[0]?.cause,
  }).toEqual({
    outcome: {rejected: true, reason: 'string boom'},
    count: 1,
    isError: true,
    message: 'string boom',
    cause: 'string boom',
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
